functions.showTrophyUnlocked:
function showTrophyUnlocked(trophy) {
  // Lazy init for state vars (live on window so they survive across the
  // queue + playback handoff between this function and _playNextTrophy).
  if (typeof window._trophyQueue === "undefined") {
    window._trophyQueue = [];
    window._trophyIsShowing = false;
    window._trophyShownIds = {};
  }
  if (typeof document === "undefined") return;
  var tid = trophy && trophy.id;
  if (tid && window._trophyShownIds[tid]) return;
  if (tid) window._trophyShownIds[tid] = true;
  window._trophyQueue.push(trophy);
  if (!window._trophyIsShowing) _playNextTrophy();
}

functions._playNextTrophy:
function _playNextTrophy() {
  if (window._trophyQueue.length === 0) {
    window._trophyIsShowing = false;
    return;
  }
  window._trophyIsShowing = true;
  var trophy = window._trophyQueue.shift();
  var colors = ["#febb02", "#f15025", "#4285f4", "#0f9d58", "#9c27b0", "#00bcd4"];
  var confettiContainer = document.createElement("div");
  confettiContainer.style.position = "absolute";
  confettiContainer.style.top = "0";
  confettiContainer.style.left = "0";
  confettiContainer.style.width = "100%";
  confettiContainer.style.height = "100%";
  confettiContainer.style.pointerEvents = "none";
  confettiContainer.style.zIndex = "9998";
  confettiContainer.style.overflow = "hidden";
  document.body.appendChild(confettiContainer);
  for (var i = 0; i < 50; i++) {
    var conf = document.createElement("div");
    conf.style.position = "absolute";
    conf.style.width = Math.random() * 8 + 4 + "px";
    conf.style.height = Math.random() * 8 + 4 + "px";
    conf.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
    conf.style.left = Math.random() * 100 + "%";
    conf.style.top = "-10px";
    conf.style.opacity = Math.random() + 0.5;
    conf.style.transform = "rotate(" + Math.random() * 360 + "deg)";
    conf.style.transition = "transform 3s linear, top 3s ease-in, opacity 3s ease-out";
    confettiContainer.appendChild(conf);
    void conf.offsetWidth;
    var endTop = 100 + Math.random() * 20 + "%";
    var endRot = Math.random() * 720 - 360 + "deg";
    conf.style.top = endTop;
    conf.style.transform = "rotate(" + endRot + ")";
    conf.style.opacity = "0";
  }
  setTimeout(function () {
    if (confettiContainer.parentNode) confettiContainer.parentNode.removeChild(confettiContainer);
  }, 3000);
  var toast = document.createElement("div");
  toast.style.position = "absolute";
  toast.style.top = "-100px";
  toast.style.left = "50%";
  toast.style.transform = "translateX(-50%)";
  toast.style.background = "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)";
  toast.style.color = "#fff";
  toast.style.padding = "16px 20px";
  toast.style.borderRadius = "20px";
  toast.style.boxShadow = "0 10px 30px rgba(0,0,0,0.3), 0 0 0 1px rgba(255,255,255,0.1)";
  toast.style.display = "flex";
  toast.style.alignItems = "center";
  toast.style.gap = "14px";
  toast.style.zIndex = "9999";
  toast.style.transition = "all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)";
  toast.innerHTML = `
        <div style="font-size:32px; filter:drop-shadow(0 2px 4px rgba(0,0,0,0.2));">${trophy.icon}</div>
        <div>
            <div class="eli-label-sm" style="color:#38bdf8;">Achievement Unlocked</div>
            <div style="font-size:15px; font-weight:700; color:#f8fafc;">${trophy.title}</div>
            <div style="font-size:11px; color:#94a3b8; margin-top:2px;">${trophy.desc}</div>
        </div>
    `;
  document.body.appendChild(toast);
  setTimeout(function () {
    toast.style.top = "30px";
  }, 50);
  setTimeout(function () {
    toast.style.top = "-100px";
    toast.style.opacity = "0";
    setTimeout(function () {
      if (toast.parentNode) toast.parentNode.removeChild(toast);
      _playNextTrophy();
    }, 600);
  }, 4500);
}

