  var rankThresholds = [
    { name: "Novice", min: 0 },
    { name: "Specialist", min: 20 },
    { name: "Strategist", min: 40 },
    { name: "Architect", min: 60 },
    { name: "Executive", min: 80 },
    { name: "Grandmaster", min: 100 },
  ];
  var currentRankIdx = 0;
  for (var ri = rankThresholds.length - 1; ri >= 0; ri--) {
    if (trophyCount >= rankThresholds[ri].min) {
      currentRankIdx = ri;
      break;
    }
