      } else if (isNext) {
        return (
          '<span style="font-size:9px; font-weight:900; color:#fbbf24; text-shadow:0 0 10px rgba(251,191,36,0.5); animation:pulse 2s infinite;">→ ' +
          r.toUpperCase() +
