                <div onclick="document.getElementById('trophy-details-modal').style.opacity='0'; setTimeout(function(){document.getElementById('trophy-details-modal').remove();}, 300);" class="eli-modal-close-x">&times;</div>
                <div style="color:#fbbf24; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px; margin-bottom:16px; text-shadow:0 0 10px rgba(251,191,36,0.5);">Achievement Unlocked</div>
                <div style="font-size:72px; line-height:1; margin-bottom:16px; filter:drop-shadow(0 10px 20px rgba(251,191,36,0.4)); animation: pulse 2s infinite;">${trophy.icon}</div>
                <div style="font-size:24px; font-weight:900; color:#fff; margin-bottom:8px;">${trophy.title}</div>
                <div class="eli-label-sm" style="color:#34d399; margin-bottom:12px;">✓ AWARDED ON ${dateStr}</div>
                <div style="font-size:13px; color:#cbd5e1; line-height:1.5; margin-bottom:24px;">${trophy.desc}</div>
                <button data-clip="${copyText}" onclick="${copyAction}" style="background:rgba(251,191,36,0.15); border:1px solid rgba(251,191,36,0.5); color:#fbbf24; padding:12px 24px; border-radius:0; font-size:14px; font-weight:800; cursor:pointer; width:100%; transition:all 0.2s; margin-bottom:10px;" onmouseover="this.style.background='rgba(251,191,36,0.25)';" onmouseout="this.style.background='rgba(251,191,36,0.15)';">📋 Share Achievement</button>
            </div>
        `;
  } else {
    var currentScore = typeof trophy.getProgress === "function" ? trophy.getProgress(stats) : stats[trophy.metric] || 0;
    var progressHtml = "";
    if (trophy.target > 1) {
      var pct = Math.min(100, Math.round((currentScore / trophy.target) * 100));
      progressHtml = `
                <div style="margin-top:24px; width:100%; text-align:left;">
                    <div style="display:flex; justify-content:space-between; font-size:11px; font-weight:800; color:#94a3b8; margin-bottom:8px; text-transform:uppercase;">
                        <span>Progress</span>
                        <span style="color:#fff;">${currentScore.toLocaleString()} / ${trophy.target.toLocaleString()}</span>
                    </div>
                    <div style="width:100%; height:8px; background:rgba(255,255,255,0.05); border-radius:4px; overflow:hidden; border:1px solid rgba(255,255,255,0.1);">
                        <div style="width:${pct}%; height:100%; background:linear-gradient(90deg, #3b82f6, #60a5fa); border-radius:4px; box-shadow:0 0 10px rgba(59,130,246,0.5);"></div>
                    </div>
                </div>
            `;
    } else {
      progressHtml = `
                <div style="margin-top:24px; font-size:12px; font-weight:600; color:#64748b; font-style:italic;">
                    Keep exploring ELI to discover this achievement.
                </div>
            `;
    }
    contentHtml = `
            <div style="background:#1e293b; border:1px solid rgba(255,255,255,0.1); box-shadow:0 20px 40px rgba(0,0,0,0.6); border-radius:0; width:300px; padding:32px 24px; text-align:center; position:relative; transform:scale(0.9); transition:transform 0.3s cubic-bezier(0.16,1,0.3,1);" id="trophy-modal-box">
                <div onclick="document.getElementById('trophy-details-modal').style.opacity='0'; setTimeout(function(){document.getElementById('trophy-details-modal').remove();}, 300);" class="eli-modal-close-x">&times;</div>
                <div style="color:#64748b; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px; margin-bottom:16px;">Locked Trophy</div>
                <div style="font-size:72px; line-height:1; margin-bottom:16px; filter:grayscale(100%) opacity(0.3);">${trophy.icon}</div>
                <div style="font-size:20px; font-weight:900; color:#94a3b8; margin-bottom:8px;">${trophy.title}</div>
                <div style="font-size:12px; color:#64748b; line-height:1.5;">${trophy.desc}</div>
                ${progressHtml}
            </div>
        `;
  }
  modalOverlay.innerHTML = contentHtml;
  document.body.appendChild(modalOverlay);
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      modalOverlay.style.opacity = "1";
      var box = document.getElementById("trophy-modal-box");
      if (box) box.style.transform = "scale(1)";
    });
  });
}
